// ---- Leaderboard setup: paste your Firebase Realtime Database URL to share scores between students.
// Example: 'https://my-college-game-default-rtdb.firebaseio.com'  (leave '' to keep scores on this device only)
const FIREBASE_URL = 'https://space-fight-80a52-default-rtdb.asia-southeast1.firebasedatabase.app';

const cv = document.getElementById('g'), x = cv.getContext('2d'), W = 360, H = 560;
cv.width = W; cv.height = H;
const C = { hot: '#ffb23e', foe: '#4be0c0', foe2: '#ff5d8f', ink: '#f2efff', blue: '#7ad7ff' };
const iTri = new Image(), iRap = new Image(); iTri.src = 'data:image/png;base64,'; iRap.src = 'data:image/png;base64,';
const img = new Image(); img.src = 'data:image/png;base64,';
const COM = ['', '', '', '', '', ''].map(d => { const i = new Image(); i.src = 'data:image/png;base64,' + d; return i }), BOS = ['', '', ''].map(d => { const i = new Image(); i.src = 'data:image/png;base64,' + d; return i }), FLIP = [5];
let boss = null, bn = 0, bossMode = false;
let st = 'menu', score = 0, lives = 3, wave = 1, t = 0, me, bul = [], eb = [], en = [], orbs = [], fm, pa = [], shootCd = 0, diveCd = 2, eCd = 1, inv = 0, tx = null, keys = {}, rapid = 0, triple = 0;
const stars = Array.from({ length: 60 }, () => ({ x: Math.random() * W, y: Math.random() * H, s: Math.random() * 1.6 + .4, v: Math.random() * 50 + 15 }));
const ov = document.getElementById('ov'), sc = document.getElementById('sc'), sub = document.getElementById('sub'), go = document.getElementById('go'), nm = document.getElementById('nm'), lb = document.getElementById('lb'), note = document.getElementById('note'), h1 = document.getElementById('ttl');
function lockName() { nm.readOnly = true; nm.title = 'Your name is locked on this device' }
try { const sv = localStorage.getItem('gf-name'); if (sv) { nm.value = sv; lockName(); sub.textContent = 'Playing as ' + sv + '. Drag to move, your ship fires by itself. Catch orbs for rapid ammo and triple shot.' } } catch (e) { }

// ---- Leaderboard
// Show each player once, with only their highest score (also hides any older duplicate entries).
function best(list) {
    const m = {};
    for (const r of list) { const k = String(r.name || 'Anon').toLowerCase().trim(); if (!m[k] || m[k].score < r.score) m[k] = r }
    return Object.values(m).sort((a, b) => b.score - a.score).slice(0, 10);
}
async function getBoard() {
    if (FIREBASE_URL) {
        try {
            const r = await fetch(FIREBASE_URL + '/scores.json?orderBy="score"&limitToLast=60');
            return best(Object.values(await r.json() || {}));
        } catch (e) { }
    }
    try { return best(JSON.parse(localStorage.getItem('gf-board') || '[]')) } catch (e) { return [] }
}
// One entry per player: the key is the name, and a score is only saved if it beats that player's best.
async function addScore(name, s) {
    const key = name.toLowerCase().replace(/[.$#\[\]\/\s]+/g, '-').slice(0, 16) || 'anon';
    if (FIREBASE_URL) {
        try {
            const u = FIREBASE_URL + '/scores/' + encodeURIComponent(key) + '.json';
            const old = await (await fetch(u)).json();
            if (!old || old.score < s) await fetch(u, { method: 'PUT', body: JSON.stringify({ name, score: s, t: Date.now() }) });
            return;
        } catch (e) { }
    }
    try {
        const b = JSON.parse(localStorage.getItem('gf-board') || '[]');
        const i = b.findIndex(r => r.key === key);
        if (i < 0) b.push({ key, name, score: s }); else if (b[i].score < s) b[i] = { key, name, score: s };
        b.sort((p, q) => q.score - p.score); localStorage.setItem('gf-board', JSON.stringify(b.slice(0, 10)));
    } catch (e) { }
}
async function showBoard() {
   note.textContent='';
    const b = await getBoard(); lb.innerHTML = '';
    if (!b.length) { const li = document.createElement('li'); li.textContent = 'No scores yet. Be the first.'; lb.appendChild(li); return }
    for (const r of b) {
        const li = document.createElement('li'), sp = document.createElement('span');
        li.textContent = String(r.name || 'Anon').slice(0, 16); sp.textContent = r.score; li.appendChild(sp); lb.appendChild(li);
    }
}
showBoard();

// ---- Game
function spawn() {
    en = []; fm = { off: 0, dir: 1 }; const rows = Math.min(3 + Math.floor(wave / 2), 5);
    for (let r = 0; r < rows; r++)for (let c = 0; c < 7; c++)en.push({ r, c, x: W / 2 + (c - 3) * 40, y: -30 - r * 34 - c * 6, bx: 0, t: 0, sp: (r + wave) % 6, s: 'enter', alive: true });
}
function start() {
    const nmv = nm.value.trim();
    if (!nmv) { nm.focus(); sc.textContent = 'Enter your name to start'; return }
    if (!nm.readOnly) { try { localStorage.setItem('gf-name', nmv) } catch (e) { } lockName() }
    sc.textContent = '';
    boss = null; bossMode = false; bn = 0; score = 0; lives = 3; wave = 1; me = { x: W / 2, y: 505 }; bul = []; eb = []; orbs = []; pa = []; shootCd = 0; diveCd = 2; eCd = 1; inv = 0; tx = null; rapid = 0; triple = 0;
    spawn(); st = 'play'; ov.classList.add('off');
}
function spark(px, py, col) { for (let i = 0; i < 14; i++) { const a = Math.random() * 6.28, v = 40 + Math.random() * 120; pa.push({ x: px, y: py, vx: Math.cos(a) * v, vy: Math.sin(a) * v, l: .5, c: col }) } }
async function over() {
    st = 'over'; h1.textContent = 'Game over';
    sub.textContent = 'You reached wave ' + wave + '.'; sc.textContent = 'Score ' + score;
    go.textContent = 'Play again'; ov.classList.remove('off');
    await addScore(nm.value.trim() || 'Anon', score); showBoard();
}
function hit() { lives--; inv = 1.8; spark(me.x, me.y, C.blue); eb = []; rapid = 0; triple = 0; if (lives <= 0) over() }
function update(dt) {
    for (const s of stars) { s.y += s.v * dt; if (s.y > H) { s.y = 0; s.x = Math.random() * W } }
    for (const p of pa) { p.x += p.vx * dt; p.y += p.vy * dt; p.l -= dt }
    pa = pa.filter(p => p.l > 0);
    if (st !== 'play') return;
    t += dt;
    if (tx !== null) me.x += (tx - me.x) * Math.min(1, dt * 14);
    if (keys.ArrowLeft) { me.x -= 250 * dt; tx = null }
    if (keys.ArrowRight) { me.x += 250 * dt; tx = null }
    me.x = Math.max(18, Math.min(W - 18, me.x));
    inv -= dt; shootCd -= dt; rapid -= dt; triple -= dt; bn -= dt;
    if (shootCd <= 0) {
        const vs = triple > 0 ? [-90, 0, 90] : [0];
        for (const vx of vs) bul.push({ x: me.x, y: me.y - 18, vx });
        shootCd = rapid > 0 ? .12 : .26;
    }
    for (const b of bul) { b.y -= 540 * dt; b.x += b.vx * dt }
    bul = bul.filter(b => b.y > -10 && b.x > -10 && b.x < W + 10 && !b.dead);
    fm.off += fm.dir * (28 + wave * 6) * dt;
    if (Math.abs(fm.off) > 40) { fm.dir *= -1; fm.off = Math.sign(fm.off) * 40 }
    for (const e of en) {
        if (!e.alive) continue;
        const sx = W / 2 + (e.c - 3) * 40 + fm.off, sy = 70 + e.r * 34 + Math.sin(t * 2 + e.c) * 3;
        if (e.s === 'enter') { e.y += 150 * dt; e.x += (sx - e.x) * dt * 4; if (e.y >= sy) e.s = 'form' }
        else if (e.s === 'form') { e.x = sx; e.y = sy }
        else { e.t += dt; e.y += (120 + wave * 10) * dt; e.x = Math.max(14, Math.min(W - 14, e.bx + Math.sin(e.t * 3) * 70)); if (e.y > H + 20) { e.s = 'enter'; e.y = -20 } }
    }
    diveCd -= dt;
    if (diveCd <= 0) {
        const f = en.filter(e => e.alive && e.s === 'form');
        if (f.length) { const e = f[Math.floor(Math.random() * f.length)]; e.s = 'dive'; e.bx = e.x; e.t = 0 }
        diveCd = Math.max(.8, 2.4 - wave * .2);
    }
    eCd -= dt;
    if (eCd <= 0) {
        const f = en.filter(e => e.alive && e.s !== 'enter' && e.y > 0);
        if (f.length) { const e = f[Math.floor(Math.random() * f.length)]; eb.push({ x: e.x, y: e.y + 10 }) }
        eCd = Math.max(.35, 1.1 - wave * .08);
    }
    for (const b of eb) { b.y += (200 + wave * 12) * dt; b.x += (b.vx || 0) * dt }
    eb = eb.filter(b => b.y < H + 10 && b.x > -10 && b.x < W + 10);
    for (const o of orbs) { o.y += 90 * dt; o.p += dt * 6 }
    orbs = orbs.filter(o => o.y < H + 14 && !o.dead);
    for (const o of orbs) if (Math.abs(o.x - me.x) < 22 && Math.abs(o.y - me.y) < 24) {
        o.dead = true; spark(o.x, o.y, o.k === 'r' ? C.hot : C.blue);
        if (o.k === 'r') rapid = 8; else triple = 8; score += 25;
    }
    for (const b of bul) for (const e of en) {
        if (e.alive && !b.dead && Math.abs(b.x - e.x) < 15 && Math.abs(b.y - e.y) < 13) {
            e.alive = false; b.dead = true; score += e.s === 'dive' ? 50 : 10 + (4 - Math.min(e.r, 4)) * 2;
            spark(e.x, e.y, e.r % 2 ? C.foe2 : C.foe);
            if (Math.random() < .13) orbs.push({ x: e.x, y: e.y, k: Math.random() < .5 ? 'r' : 't', p: 0 });
        }
    }
    if (boss) {
        boss.t += dt; boss.fl -= dt; boss.cd -= dt;
        boss.x = W / 2 + Math.sin(boss.t * .9) * 100;
        boss.y += ((90 + Math.sin(boss.t * 1.7) * 10) - boss.y) * Math.min(1, dt * 2.5);
        if (boss.cd <= 0 && boss.t > 1.2) {
            const vs = boss.n % 2 ? [-70, 0, 70] : [-120, -60, 0, 60, 120]; boss.n++;
            for (const vx of vs) eb.push({ x: boss.x, y: boss.y + 30, vx });
            boss.cd = Math.max(.7, 1.3 - boss.num * .08);
        }
        for (const b of bul) if (!b.dead && Math.abs(b.x - boss.x) < 38 && Math.abs(b.y - boss.y) < 34) { b.dead = true; boss.hp--; boss.fl = .08; spark(b.x, b.y, C.hot) }
        if (boss.hp <= 0) {
            score += 500 * boss.num;
            for (let i = 0; i < 5; i++)spark(boss.x + (Math.random() - .5) * 70, boss.y + (Math.random() - .5) * 60, i % 2 ? C.hot : C.foe2);
            orbs.push({ x: boss.x - 30, y: boss.y, k: 'r', p: 0 }, { x: boss.x + 30, y: boss.y, k: 't', p: 0 });
            boss = null; bossMode = false; eb = []; wave++; spawn();
        }
    }
    if (inv <= 0) {
        if (boss && Math.abs(boss.x - me.x) < 32 && Math.abs(boss.y - me.y) < 32) { hit() }
        else for (const b of eb) if (Math.abs(b.x - me.x) < 11 && Math.abs(b.y - me.y) < 14) { hit(); break }
        if (st === 'play' && inv <= 0) for (const e of en) if (e.alive && e.s !== 'enter' && Math.abs(e.x - me.x) < 18 && Math.abs(e.y - me.y) < 18) { e.alive = false; spark(e.x, e.y, C.foe); hit(); break }
    }
    if (st === 'play' && !bossMode && !en.some(e => e.alive)) {
        if (wave % 5 === 0) { bossMode = true; eb = []; bn = 2.2; const num = wave / 5; boss = { x: W / 2, y: -70, t: 0, cd: 1.5, n: 0, fl: 0, num, hp: 24 + num * 10, max: 24 + num * 10, sp: (num - 1) % 3 } }
        else { wave++; spawn(); bul = [] }
    }
}
function ship(px, py, k) {
    x.save(); x.translate(px, py); x.imageSmoothingEnabled = false;
    x.fillStyle = C.hot; x.beginPath(); x.moveTo(-4, 16 * k); x.lineTo(0, (16 + 6 + Math.random() * 6) * k); x.lineTo(4, 16 * k); x.fill();
    x.drawImage(img, -17 * k, -18 * k, 34 * k, 36 * k);
    x.restore();
}
function foe(e) {
    const im = COM[e.sp]; if (!im.complete || !im.naturalWidth) return;
    const k = Math.min(34 / im.naturalWidth, 30 / im.naturalHeight), w = im.naturalWidth * k, h = im.naturalHeight * k;
    x.save(); x.translate(e.x, e.y); if (FLIP.includes(e.sp)) x.scale(1, -1); x.drawImage(im, -w / 2, -h / 2, w, h); x.restore();
}
function drawBoss() {
    const im = BOS[boss.sp];
    if (im.complete && im.naturalWidth) {
        const k = Math.min(88 / im.naturalWidth, 80 / im.naturalHeight), w = im.naturalWidth * k, h = im.naturalHeight * k;
        x.save(); x.translate(boss.x, boss.y); x.drawImage(im, -w / 2, -h / 2, w, h);
        if (boss.fl > 0) { x.globalCompositeOperation = 'lighter'; x.drawImage(im, -w / 2, -h / 2, w, h) }
        x.restore();
    }
    x.fillStyle = '#2a2766'; x.fillRect(60, 34, W - 120, 7);
    x.fillStyle = C.foe2; x.fillRect(60, 34, (W - 120) * Math.max(0, boss.hp) / boss.max, 7);
}
function orb(o) {
    const col = o.k === 'r' ? C.hot : C.blue, r = 15 + Math.sin(o.p) * 1.5, im = o.k === 'r' ? iRap : iTri;
    x.save(); x.translate(o.x, o.y);
    x.globalAlpha = .3; x.fillStyle = col; x.beginPath(); x.arc(0, 0, r + 6, 0, 6.28); x.fill();
    x.globalAlpha = 1; x.beginPath(); x.arc(0, 0, r, 0, 6.28); x.fill();
    if (im.complete && im.naturalWidth) { const f = o.k === 'r' ? 1.85 : 1.5, k = Math.min(r * f / im.naturalWidth, r * f / im.naturalHeight), w = im.naturalWidth * k, h = im.naturalHeight * k; x.drawImage(im, -w / 2, -h / 2, w, h) }
    x.restore();
}
function draw() {
    x.fillStyle = '#0b0a1f'; x.fillRect(0, 0, W, H); x.fillStyle = '#cfc8ff';
    for (const s of stars) { x.globalAlpha = .35 + s.s / 3; x.fillRect(s.x, s.y, s.s, s.s) }
    x.globalAlpha = 1;
    if (st !== 'menu') {
        for (const e of en) if (e.alive) foe(e);
        if (boss) drawBoss();
        for (const o of orbs) orb(o);
        x.fillStyle = C.hot; for (const b of bul) x.fillRect(b.x - 1.5, b.y - 8, 3, 12);
        x.fillStyle = C.foe2; for (const b of eb) { x.beginPath(); x.arc(b.x, b.y, 4, 0, 6.28); x.fill() }
        if (st === 'play' && (inv <= 0 || Math.floor(inv * 10) % 2)) ship(me.x, me.y, 1);
        for (const p of pa) { x.globalAlpha = Math.max(0, p.l * 2); x.fillStyle = p.c; x.fillRect(p.x, p.y, 3, 3) }
        x.globalAlpha = 1; x.fillStyle = C.ink; x.font = '700 16px Arial,sans-serif'; x.textBaseline = 'alphabetic';
        x.textAlign = 'left'; x.fillText('Score ' + score, 12, 24);
        x.textAlign = 'right'; x.fillText(bossMode ? 'BOSS' : 'Wave ' + wave, W - 12, 24);
        if (bn > 0) { x.save(); x.textAlign = 'center'; x.fillStyle = C.hot; x.font = '700 28px Arial,sans-serif'; x.fillText('BOSS INCOMING', W / 2, H / 2 - 30); x.restore() }
        for (let i = 0; i < lives; i++)ship(24 + i * 26, H - 26, .5);
        x.textAlign = 'right'; let y = H - 34;
        if (rapid > 0) { x.fillStyle = C.hot; x.fillText('Rapid ammo ' + Math.ceil(rapid) + 's', W - 12, y); y -= 22 }
        if (triple > 0) { x.fillStyle = C.blue; x.fillText('Triple shot ' + Math.ceil(triple) + 's', W - 12, y) }
    }
}
let last = performance.now();
function loop(n) { const dt = Math.min(.05, (n - last) / 1000); last = n; update(dt); draw(); requestAnimationFrame(loop) }
requestAnimationFrame(loop);
function pos(ev) { const r = cv.getBoundingClientRect(); tx = (ev.clientX - r.left) * W / r.width }
cv.addEventListener('pointermove', pos); cv.addEventListener('pointerdown', pos);
addEventListener('keydown', ev => { if (document.activeElement === nm) return; keys[ev.key] = true; if (ev.key.startsWith('Arrow')) ev.preventDefault() });
addEventListener('keyup', ev => { keys[ev.key] = false });
go.addEventListener('click', () => { h1.textContent = 'Galaxy Fight'; start() });